public Set getPricingAttributes()
{
    var attrSet = new Set(Types::AnyType);

    EcoResAttribute ecoResAttribute;
    EcoResAttributeType ecoResAttributeType;
    UPSEcoResAttributeParameter attributeParameter;

    while select Name from ecoResAttribute
        group by Name
        join attributeParameter
        where ecoResAttribute.RecId == attributeParameter.Attribute
            && attributeParameter.IsEnabledAsPricingAttribute == NoYes::Yes
        join Name from ecoResAttributeType
        group by Name
        where ecoResAttribute.AttributeType == ecoResAttributeType.RecId
    {
        attrSet.add(new UPSPricingAttributeEcoResAttribute(ecoResAttribute.Name, ecoResAttributeType.Name, this));
    }

    return attrSet;
}

// Attribute with Fixed-list == Yes. 
public Set getAllowedValues(UPSIPricingAttribute _attribute)
{
    var ret = new Set(Types::String);
    UPSPricingAttributeEcoResAttribute attr = _attribute;

    EcoResAttributeType attributeType;
    EcoResEnumerationAttributeTypeValue enumerationAttributeTypeValue;
    EcoResValue value;

    while select attributeType
            where attributeType.Name == attr.getAttributeType()
            join enumerationAttributeTypeValue
            where enumerationAttributeTypeValue.AttributeType == attributeType.RecId
            join * from value
            where value.RecId == enumerationAttributeTypeValue.Value
    {
        if ((value as EcoResTextValue).textValue)
        {
            ret.add(any2Str((value as EcoResTextValue).textValue));
        }
        else if ((value as EcoResIntValue).intValue)
        {
            ret.add(any2Str((value as EcoResIntValue).intValue));
        }
    }

    return ret;
}

abstract public Query buildPricingObjectQuery(Query _query, UPSIPricingAttribute _pricingAttr, anytype _value, Map _qbdsMap = null)
{
}

protected AttributeDataType getAttributeType(str _pricingAttrName)
{
    EcoResAttribute attr;

    select firstonly attr where attr.Name == _pricingAttrName;

    return attr.getActualDataType();
}
